"""Geometry-based regression tests for the wallpaper area calculation."""

import unittest

from src.component import calculate_black_area_doubled


def cell_area_doubled(x: int, y: int) -> int:
    """Color the two half-square triangles directly from the line equations."""
    black_triangles = 0
    for offset in (1, 2):
        # Triangle centroids are (x + offset/3, y + offset/3).
        # Each crossed vertical, horizontal, or diagonal line flips the color.
        parity = x + (3 * y + offset) // 6 + (3 * (x + y) + 2 * offset) // 6
        black_triangles += parity % 2 == 0
    return black_triangles


class WallpaperAreaTests(unittest.TestCase):
    def test_individual_cells(self):
        for x in range(-9, 10):
            for y in range(-9, 10):
                with self.subTest(x=x, y=y):
                    self.assertEqual(
                        calculate_black_area_doubled(x, y, x + 1, y + 1),
                        cell_area_doubled(x, y),
                    )

    def test_exhaustive_small_rectangles(self):
        for a in range(-5, 5):
            for c in range(a + 1, 6):
                for b in range(-5, 5):
                    for d in range(b + 1, 6):
                        expected = sum(
                            cell_area_doubled(x, y)
                            for x in range(a, c)
                            for y in range(b, d)
                        )
                        self.assertEqual(
                            calculate_black_area_doubled(a, b, c, d),
                            expected,
                            (a, b, c, d),
                        )

    def test_large_translations_preserve_the_pattern(self):
        for dx, dy in ((-999_999_992, -999_999_992),
                       (999_999_992, 999_999_992),
                       (-999_999_992, 999_999_992)):
            self.assertEqual(
                calculate_black_area_doubled(-3 + dx, -5 + dy, 6 + dx, 7 + dy),
                calculate_black_area_doubled(-3, -5, 6, 7),
            )

    def test_full_tiles_at_large_bounds(self):
        self.assertEqual(
            calculate_black_area_doubled(-10**9, -10**9, 10**9, 10**9),
            4 * 10**18,
        )
        self.assertEqual(
            calculate_black_area_doubled(-10**9, 10**9 - 1, 10**9, 10**9),
            2 * 10**9,
        )
        self.assertEqual(
            calculate_black_area_doubled(10**9 - 1, -10**9, 10**9, 10**9),
            10**9,
        )


if __name__ == '__main__':
    unittest.main()
